fn split<T>(result:Result<T,Failure>)->io::Result<Result<T,String>>{match result{Ok(value)=>Ok(Ok(value)),Err(Failure::Operational(actual))=>Err(actual),Err(Failure::Unsupported(message))=>Ok(Err(message))}}
