    let request=Request::Read{receiver:receiver.to_owned(),procedure:procedure.to_owned(),context:binding.map(str::to_owned),flavor};let mut child=Params{semantic:None,generator:None,policy:false,selected_setter_tree:false,key:p.key,issuance:p.issuance,evidence:p.evidence,locator:p.locator,configuration:p.configuration,configuration_path:p.configuration_path.clone(),root:p.root.clone(),request};child.key=key_for(&child,&child.request)?;let value={get_current(&mut context.borrow_mut(),child,&loan,admission)?};
