impl QueryDb{
 /// Internal whole-handler child route. The private whole report already owns
 /// the raw-family gate and the real full reader; reuse that reader's root
 /// Budget and current subject rather than relocking or minting a second one.
 pub(super) fn with_handler_declarations_reader_locked<T>(&self,workspace:&Arc<WorkspaceCapture>,guard:&crate::runner_host::query_snapshot::workspace_native_guard::NativeReadGuard<'_>,capture:&Arc<CapturedPolicyInputs>,reader:&WorkspaceCodeReader<'_,'_>,selected_full:bool,consume:impl FnOnce(&dq_analyze::captured_reactive_reads::UnsealedHandlerDeclarations,&Arc<Budget>)->io::Result<T>)->Result<T,Failure>{
  use crate::policy_request::WorkspaceAuxiliaryQuestion as Q;
  crate::daemon::control::checkpoint()?;workspace.require_scope(guard)?;
  let subject=capture.original_analysis_subject().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"handler declarations lack independently requested full Subject"))?;
  workspace.require_analysis_subject(subject)?;subject.require_bound_mapping(capture.policy().mapping())?;
  let question=if selected_full{Q::SemHandlersFullAllow}else{Q::SemHandlers};
  if !guard.uses_queries(self)||!workspace.matches_auxiliary_questions(&[question])||capture.policy().mapping().initial_environment()!=dm_preprocess::InitialEnvironment::OriginalChecker0290||!matches!(guard.model_preparation(),Some(dm_tree::frontend::DiagnosticPreparationPurpose::OriginalSharedComplete|dm_tree::frontend::DiagnosticPreparationPurpose::OriginalAnalyzePrefix)){return Err(Failure::Operational(io::Error::new(io::ErrorKind::InvalidInput,"handler declaration child has no independent actual full source purpose")))}
  reader.budget().charge(2*std::mem::size_of::<usize>()).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;
  let scope=guard.query_receipt(&mut|bytes|reader.budget().charge(bytes).map_err(|message|io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let scope=Arc::new(scope);
  let produced=flatten(scope.with_guard(self,workspace,capture.policy(),|current|split(self.with_workspace_policy_job_reader_contract(workspace,&scope,capture,Request::Globals,Some(SemanticPolicyName::HandlerDeclarations),None,reader,current,SemanticReportContract::Existing,|value,_config|match value{Value::SemanticPolicy(result)if result.name==SemanticPolicyName::HandlerDeclarations=>consume(result.handler_declarations().ok_or_else(||io::Error::other("handler declarations actual payload differs"))?,reader.budget()),_=>Err(io::Error::other("handler declarations actual child role differs"))}))));
  if matches!(&produced,Err(Failure::Operational(_))){return produced}if reader.budget().denied(){return Err(Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"handler declaration child admission exhausted")))}produced
 }
}

